import {takePresetGroups} from './take-preset-inheritance.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function takeInheritanceMarkup(doc,files,status){const d=doc.data,rows=files.filter(f=>f.kind==='takepreset'&&f.path!==doc.path);return '<section class="take-inheritance"><label>상위 프리셋<select data-take-parent><option value="">독립 프리셋</option>'+((d.parentPreset&&!rows.some(f=>f.path===d.parentPreset))?'<option value="'+esc(d.parentPreset)+'" selected>연결 없음 · '+esc(d.parentPreset)+'</option>':'')+rows.map(f=>'<option value="'+esc(f.path)+'" '+(f.path===d.parentPreset?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select></label>'+(d.parentPreset?'<fieldset><legend>이 프리셋에서 덮어쓰기</legend>'+takePresetGroups.map(([key,label])=>'<label><input type="checkbox" data-take-override="'+key+'" '+(d.overrides.includes(key)?'checked':'')+'>'+label+'</label>').join('')+'</fieldset><div><button type="button" data-take-inherit-refresh>상위 새로고침</button><button type="button" data-take-inherit-detach '+(status.ready?'':'disabled')+'>상속 해제</button></div><p role="status" data-take-inherit-status>'+esc(status.message)+'</p>':'')+'</section>';}
export function takePresetDisplay(element,doc,hooks,render){
 const d=doc.data;if(!d.parentPreset){delete element.hbTakePresetResolved;return {data:d,ready:true,message:''};}const state=element.hbTakePresetResolved;if(state?.source===d)return {data:state.data||d,ready:!!state.data,message:state.error||(state.data?'상위 설정 적용됨':'상위 설정 읽는 중')};
 const token={source:d};element.hbTakePresetResolved=token;Promise.resolve().then(()=>hooks.resolveTakePreset(d,doc.path)).then(data=>{if(element.hbTakePresetResolved!==token||doc.data!==d)return;token.data=data;if(element.isConnected)render();},error=>{if(element.hbTakePresetResolved!==token||doc.data!==d)return;token.error=error.message;if(element.isConnected)render();});return {data:d,ready:false,message:'상위 설정 읽는 중'};
}
export function takeInheritanceChange(input,next,display){if(input.hasAttribute('data-take-parent')){if(input.value){next.parentPreset=input.value;next.overrides=[];}else{if(next.parentPreset&&!display.ready)throw Error('상위 설정을 읽은 뒤 상속을 해제하세요.');for(const key of Object.keys(next))delete next[key];Object.assign(next,structuredClone(display.data));delete next.parentPreset;delete next.overrides;}return true;}if(input.dataset.takeOverride){const key=input.dataset.takeOverride,set=new Set(next.overrides);if(input.checked){if(!display.ready)throw Error('상위 설정을 먼저 읽으세요.');if(display.data[key]===undefined)delete next[key];else next[key]=structuredClone(display.data[key]);set.add(key);}else set.delete(key);next.overrides=[...set];return true;}return false;}
export function lockInheritedTakeControls(element,data){if(!data.parentPreset)return;const own=new Set(data.overrides),disable=selector=>{for(const e of element.querySelectorAll(selector))e.disabled=true;};for(const key of['fps','tolerance'])if(!own.has(key))disable('[data-take-asset="'+key+'"]');if(!own.has('sources'))disable('[data-take-source-mode],[data-take-source-field],[data-take-source-type],[data-take-source-add],[data-take-source-selection],[data-take-source-remove]');if(!own.has('settings'))disable('[data-take-preset],[data-take-bones],[data-take-option],[data-take-property],[data-take-filter]');}
